API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(AWS_API_Gateway_HTTP_API, "AWS API Gateway HTTP API", "AWS API Gateway", "Provides low-latency edge routing and rate limiting for incoming payment authorizations.")
    Component(Lambda_Authorizer, "Lambda Authorizer", "Rust / Go Lambda", "Authorizes and validates incoming payment authorization requests at the edge.")
}

Rel(AWS_API_Gateway_HTTP_API, Lambda_Authorizer, "Invokes for request authorization", "Internal")

@enduml

Event Stream.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(event_stream, "Event Stream") {
    Component(AmazonKinesisDataStreams, "Amazon Kinesis Data Streams", "AWS Kinesis", "Ingests and distributes real-time asynchronous decision events from the Scoring Engine.")
    Component(AmazonKinesisDataFirehose, "Amazon Kinesis Data Firehose", "AWS Kinesis Data Firehose", "Batches and streams decision data from the data stream into long-term storage.")
}

Rel(AmazonKinesisDataStreams, AmazonKinesisDataFirehose, "Streams decision events for batch processing and archiving", "AWS Internal HTTPS")

@enduml
